package com.extendedignorelist;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("extendedignorelist")
public interface ExtendedIgnoreListConfig extends Config
{
    @ConfigItem(
        keyName = "playerMenuOption",
        name = "Player Menu Option",
        description = "Show an Add ignore option on player menus",
        position = 0
    )
    default boolean playerMenuOption()
    {
        return true;
    }

    @ConfigItem(
        keyName = "ignoreListMenuOption",
        name = "Ignore List Menu Option",
        description = "Show an Add to extended option on native ignore-list entries",
        position = 1
    )
    default boolean ignoreListMenuOption()
    {
        return true;
    }

    @ConfigItem(
        keyName = "ignoreTrades",
        name = "Ignore Trades",
        description = "Hide incoming trade request messages from players on the extended ignore list",
        position = 2
    )
    default boolean ignoreTrades()
    {
        return true;
    }

    @ConfigItem(
        keyName = "deleteConfirmation",
        name = "Delete Confirmation",
        description = "Ask for confirmation before deleting a player from the extended ignore list",
        position = 3
    )
    default boolean deleteConfirmation()
    {
        return true;
    }

    @ConfigItem(
        keyName = "hidePlayers",
        name = "Hide Players",
        description = "Hide ignored players from the scene",
        position = 4
    )
    default boolean hidePlayers()
    {
        return false;
    }

    @ConfigItem(
        keyName = "syncRemoveIgnore",
        name = "Sync Remove Ignore",
        description = "Remove players from the extended ignore list when they are removed from RuneScape's native ignore list",
        position = 5
    )
    default boolean syncRemoveIgnore()
    {
        return false;
    }
}

package com.extendedignorelist;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.JOptionPane;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class ExtendedIgnoreListPanel extends PluginPanel
{
    private static final Color PANEL_BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
    private static final Color HEADER_BACKGROUND = ColorScheme.MEDIUM_GRAY_COLOR;
    private static final Color HEADER_TEXT = ColorScheme.BRAND_ORANGE;
    private static final Color LIST_FRAME = ColorScheme.BORDER_COLOR;
    private static final Color LIST_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color PRIMARY_TEXT = ColorScheme.TEXT_COLOR;
    private static final Color SECONDARY_TEXT = ColorScheme.LIGHT_GRAY_COLOR;
    private static final String NOTE_ICON_TEXT = "\u25A4";
    private static final String PREVIOUS_NAME_ICON_TEXT = "\u21C4";
    private static final int ROW_HEIGHT = 24;

    private final JPanel playersListPanel = new JPanel();
    private final Consumer<String> removePlayerAction;
    private final BiConsumer<String, String> editNoteAction;
    private final JButton importButton;

    public ExtendedIgnoreListPanel(Runnable importAction, Consumer<String> removePlayerAction, BiConsumer<String, String> editNoteAction)
    {
        super(false);
        this.removePlayerAction = removePlayerAction;
        this.editNoteAction = editNoteAction;
        setLayout(new BorderLayout());
        setBackground(PANEL_BACKGROUND);

        JPanel content = new JPanel(new BorderLayout(0, 8));
        content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        content.setBackground(PANEL_BACKGROUND);

        JPanel topPanel = new JPanel();
        topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));
        topPanel.setOpaque(false);

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(HEADER_BACKGROUND);
        headerPanel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(LIST_FRAME),
            BorderFactory.createEmptyBorder(5, 8, 5, 8)
        ));

        JLabel titleLabel = new JLabel("Extended Ignores");
        titleLabel.setForeground(HEADER_TEXT);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD));
        headerPanel.add(titleLabel, BorderLayout.WEST);

        JPanel listContainer = new JPanel(new BorderLayout());
        listContainer.setBorder(BorderFactory.createLineBorder(LIST_FRAME));
        listContainer.setBackground(LIST_BACKGROUND);

        importButton = new JButton("Import ignore list");
        importButton.setFocusPainted(false);
        importButton.setBackground(HEADER_BACKGROUND);
        importButton.setForeground(PRIMARY_TEXT);
        importButton.setBorder(BorderFactory.createLineBorder(LIST_FRAME));
        importButton.addActionListener(event -> importAction.run());
        importButton.setAlignmentX(LEFT_ALIGNMENT);
        importButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, importButton.getPreferredSize().height));

        playersListPanel.setBackground(LIST_BACKGROUND);
        playersListPanel.setLayout(new BoxLayout(playersListPanel, BoxLayout.Y_AXIS));

        JScrollPane listScrollPane = new JScrollPane(playersListPanel);
        listScrollPane.setBorder(BorderFactory.createEmptyBorder());
        listScrollPane.getViewport().setBackground(LIST_BACKGROUND);
        listScrollPane.getVerticalScrollBar().setUnitIncrement(16);

        listContainer.add(listScrollPane, BorderLayout.CENTER);

        topPanel.add(importButton);
        topPanel.add(Box.createRigidArea(new Dimension(0, 8)));
        headerPanel.setAlignmentX(LEFT_ALIGNMENT);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, headerPanel.getPreferredSize().height));
        topPanel.add(headerPanel);
        JPanel helpPanel = new JPanel();
        helpPanel.setLayout(new BoxLayout(helpPanel, BoxLayout.Y_AXIS));
        helpPanel.setOpaque(false);
        helpPanel.setAlignmentX(LEFT_ALIGNMENT);
        JLabel deleteHelpLabel = createHelpLabel("Left-click: delete");
        JLabel noteHelpLabel = createHelpLabel("Right-click: edit note");
        helpPanel.add(deleteHelpLabel);
        helpPanel.add(noteHelpLabel);
        topPanel.add(helpPanel);
        topPanel.add(Box.createRigidArea(new Dimension(0, 8)));

        content.add(topPanel, BorderLayout.NORTH);
        content.add(listContainer, BorderLayout.CENTER);

        add(content, BorderLayout.CENTER);
        // Match Notes-style behavior so this panel fills available sidebar height.
        SwingUtilities.invokeLater(() ->
        {
            if (getParent() != null)
            {
                getParent().setLayout(new BorderLayout());
                getParent().add(this, BorderLayout.CENTER);
                getParent().revalidate();
            }
        });

        renderPlayers(List.of());
        setImportButtonState(false, "Log in to import your ignore list.");
    }

    public void setPlayers(List<IgnoredPlayer> players)
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            renderPlayers(players);
            return;
        }

        SwingUtilities.invokeLater(() -> renderPlayers(players));
    }

    public void setImportButtonState(boolean enabled, String disabledReason)
    {
        Runnable update = () ->
        {
            importButton.setEnabled(enabled);
            importButton.setToolTipText(enabled ? null : disabledReason);
        };

        if (SwingUtilities.isEventDispatchThread())
        {
            update.run();
            return;
        }

        SwingUtilities.invokeLater(update);
    }

    private JLabel createHelpLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(SECONDARY_TEXT);
        label.setFont(label.getFont().deriveFont(Font.PLAIN, 13f));
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private void renderPlayers(List<IgnoredPlayer> players)
    {
        playersListPanel.removeAll();

        if (players.isEmpty())
        {
            JLabel emptyLabel = new JLabel("No players added yet.");
            emptyLabel.setForeground(SECONDARY_TEXT);
            emptyLabel.setAlignmentX(LEFT_ALIGNMENT);
            playersListPanel.add(emptyLabel);
        }
        else
        {
            for (IgnoredPlayer player : players)
            {
                playersListPanel.add(createPlayerRow(player));
            }
        }

        playersListPanel.revalidate();
        playersListPanel.repaint();
    }

    private JPanel createPlayerRow(IgnoredPlayer player)
    {
        JPanel rowPanel = new JPanel(new BorderLayout(8, 0));
        rowPanel.setOpaque(false);
        rowPanel.setAlignmentX(LEFT_ALIGNMENT);
        rowPanel.setMinimumSize(new Dimension(0, ROW_HEIGHT));
        rowPanel.setPreferredSize(new Dimension(0, ROW_HEIGHT));
        rowPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
        rowPanel.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, LIST_FRAME),
            BorderFactory.createEmptyBorder(1, 6, 1, 6)
        ));

        JPanel textPanel = new JPanel();
        textPanel.setOpaque(false);
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.add(Box.createVerticalGlue());

        JLabel playerLabel = new JLabel(player.getCurrentName());
        playerLabel.setForeground(PRIMARY_TEXT);
        JPanel namePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        namePanel.setOpaque(false);
        namePanel.add(playerLabel);

        if (!player.getNote().isEmpty())
        {
            JLabel noteIcon = new JLabel(NOTE_ICON_TEXT);
            noteIcon.setForeground(HEADER_TEXT);
            noteIcon.setToolTipText(player.getNote());
            namePanel.add(noteIcon);
        }

        textPanel.add(namePanel);

        List<String> aliases = player.getAliases();
        if (!aliases.isEmpty())
        {
            JLabel previousNameIcon = new JLabel(PREVIOUS_NAME_ICON_TEXT);
            previousNameIcon.setForeground(SECONDARY_TEXT);
            previousNameIcon.setToolTipText(String.join(", ", aliases));
            namePanel.add(previousNameIcon);
        }

        textPanel.add(Box.createVerticalGlue());

        MouseAdapter deleteClickListener = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent event)
            {
                if (event.isPopupTrigger() || event.getButton() == MouseEvent.BUTTON3)
                {
                    promptAndEditNote(player);
                    return;
                }

                if (event.getButton() == MouseEvent.BUTTON1)
                {
                    removePlayerAction.accept(player.getCurrentName());
                }
            }
        };

        rowPanel.add(textPanel, BorderLayout.CENTER);
        applyDeleteRowBehavior(rowPanel, deleteClickListener);
        return rowPanel;
    }

    private void promptAndEditNote(IgnoredPlayer player)
    {
        String note = (String) JOptionPane.showInputDialog(
            this,
            "Enter note for " + player.getCurrentName() + ":",
            "Edit note",
            JOptionPane.PLAIN_MESSAGE,
            null,
            null,
            player.getNote()
        );
        if (note != null)
        {
            editNoteAction.accept(player.getCurrentName(), note.trim());
        }
    }

    private void applyDeleteRowBehavior(Component component, MouseAdapter deleteClickListener)
    {
        component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        component.addMouseListener(deleteClickListener);

        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                applyDeleteRowBehavior(child, deleteClickListener);
            }
        }
    }

}

package com.extendedignorelist;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Ignore;
import net.runelite.api.MenuAction;
import net.runelite.api.MessageNode;
import net.runelite.api.NameableContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.api.Renderable;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.events.SessionClose;
import net.runelite.client.events.SessionOpen;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
    name = "Extended Ignore List",
    description = "Extend your ignore list limit",
    tags = {"ignore", "list", "social", "chat"}
)
public class ExtendedIgnoreListPlugin extends Plugin
{
    private static final String ADD_IGNORE_MENU_OPTION = "Add ignore";
    private static final String ADD_TO_EXTENDED_MENU_OPTION = "Add to extended";
    private static final String ADD_NAME_MENU_OPTION = "Add Name";
    private static final String REMOVE_IGNORE_MENU_OPTION = "Delete";
    private static final String REMOVE_GIM_IGNORE_MENU_OPTION = "Remove ignore";
    private static final String DEL_NAME_MENU_OPTION = "Del Name";
    private static final String CONFIG_GROUP = "extendedignorelist";
    private static final String PLAYER_MENU_OPTION_KEY = "playerMenuOption";
    private static final String LEGACY_PLAYER_MENU_OPTION_KEY = "showMenuEntryOption";
    private static final String IGNORED_PLAYERS_CONFIG_KEY = "ignoredPlayers";
    // A fixed rsprofile namespace uses RuneLite's automatically synced store without following a game account.
    private static final String SHARED_STORAGE_KEY = "rsprofile.extendedignorelist";
    private static final String LEGACY_SERIALIZED_ROW_VERSION = "v2";
    private static final String SERIALIZED_ROW_VERSION = "v3";
    private static final String CHAT_FILTER_CHECK_EVENT = "chatFilterCheck";
    private static final int NATIVE_ACTION_SYNC_TICKS = 30;

    private static final Set<ChatMessageType> FILTERED_CHAT_TYPES = EnumSet.of(
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.MODCHAT,
        ChatMessageType.PRIVATECHAT,
        ChatMessageType.MODPRIVATECHAT,
        ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT,
        ChatMessageType.CLAN_GUEST_CHAT,
        ChatMessageType.CLAN_GIM_CHAT
    );

    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RenderCallbackManager renderCallbackManager;

    @Inject
    private MenuManager menuManager;

    private final Map<String, IgnoredPlayer> ignoredPlayers = new LinkedHashMap<>();
    private final Set<String> ignoredNameIndex = new HashSet<>();

    private NavigationButton navigationButton;
    private ExtendedIgnoreListPanel panel;
    private ExtendedIgnoreListConfig activeConfig;
    private boolean updatingIgnoredPlayersConfig;
    private boolean addIgnoreMenuRegistered;
    private boolean drawListenerRegistered;
    private int pendingNativeIgnoreImportTicks;
    private int pendingNativeIgnoreRemovalTicks;
    private final Set<String> previousNativeIgnoreNames = new HashSet<>();
    private String nativeIgnoreFingerprint;
    private final Set<String> nativeIgnoreNamesBeforeAddAttempt = new HashSet<>();
    private boolean nativeAddObserved;
    private String pendingNativeAddFallbackName;
    private String nativeAddDialogBaseline;
    private String nativeAddMesLayerBaseline;
    private String nativeAddChatInputBaseline;
    private final RenderCallback drawListener = new RenderCallback()
    {
        @Override
        public boolean addEntity(Renderable renderable, boolean ui)
        {
            return shouldDraw(renderable, ui);
        }
    };

    @Provides
    ExtendedIgnoreListConfig provideConfig()
    {
        return configManager.getConfig(ExtendedIgnoreListConfig.class);
    }

    @Override
    protected void startUp()
    {
        migratePlayerMenuOptionKey();
        activeConfig = provideConfig();
        loadIgnoredPlayersForCurrentSession();
        panel = new ExtendedIgnoreListPanel(this::handleImportIgnoreList, this::handlePanelRemovePlayer, this::updatePlayerNote);
        refreshPanelPlayers();
        syncAddIgnoreMenuItem();
        syncDrawListener();

        navigationButton = NavigationButton.builder()
            .tooltip("Extended Ignore List")
            .icon(createSidebarIcon())
            .priority(5)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navigationButton);
    }

    @Override
    protected void shutDown()
    {
        if (drawListenerRegistered)
        {
            renderCallbackManager.unregister(drawListener);
            drawListenerRegistered = false;
        }
        removeAddIgnoreMenuItem();

        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
            navigationButton = null;
        }

        panel = null;
        activeConfig = null;
        ignoredPlayers.clear();
        ignoredNameIndex.clear();
    }

    public void addIgnoredPlayer(String playerName)
    {
        syncIgnoredPlayersWithNativeContainer();

        String normalizedName = normalizeName(playerName);
        if (normalizedName == null)
        {
            return;
        }

        IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(playerName);
        if (ignoredPlayer == null)
        {
            ignoredPlayer = new IgnoredPlayer(playerName);
        }

        IgnoredPlayer trackedPlayer = ignoredPlayer;
        ignoredPlayers.entrySet().removeIf(entry -> entry.getValue() == trackedPlayer);
        trackedPlayer.setCurrentName(playerName);
        trackedPlayer.addAlias(playerName);
        ignoredPlayers.put(normalizedName, trackedPlayer);
        nativeIgnoreFingerprint = null;
        persistIgnoredPlayers();
        refreshPanelPlayers();
    }

    public void removeIgnoredPlayer(String playerName)
    {
        syncIgnoredPlayersWithNativeContainer();

        IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(playerName);
        if (ignoredPlayer != null)
        {
            ignoredPlayers.entrySet().removeIf(entry -> entry.getValue() == ignoredPlayer);
            nativeIgnoreFingerprint = null;
            persistIgnoredPlayers();
            refreshPanelPlayers();
        }
    }

    private void updatePlayerNote(String playerName, String note)
    {
        IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(playerName);
        if (ignoredPlayer == null)
        {
            return;
        }

        ignoredPlayer.setNote(note);
        persistIgnoredPlayers();
        updatePanelPlayers();
    }

    private void handlePanelRemovePlayer(String playerName)
    {
        if (!provideConfig().deleteConfirmation()
            || JOptionPane.showConfirmDialog(
                panel,
                "Delete " + playerName + "?",
                "Delete Confirmation",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.QUESTION_MESSAGE
            ) == JOptionPane.YES_OPTION)
        {
            removeIgnoredPlayer(playerName);
        }
    }

    public List<IgnoredPlayer> getIgnoredPlayers()
    {
        return new ArrayList<>(ignoredPlayers.values());
    }

    private boolean shouldDraw(net.runelite.api.Renderable renderable, boolean drawingUI)
    {
        if (!(renderable instanceof net.runelite.api.Player))
        {
            return true;
        }

        net.runelite.api.Player player = (net.runelite.api.Player) renderable;
        String playerName = player.getName();
        if (playerName == null || playerName.isEmpty())
        {
            return true;
        }

        return !isIgnoredPlayerNameFast(playerName);
    }

    private void syncDrawListener()
    {
        ExtendedIgnoreListConfig config = activeConfig == null ? provideConfig() : activeConfig;
        boolean shouldRegister = config.hidePlayers();
        if (shouldRegister && !drawListenerRegistered)
        {
            renderCallbackManager.register(drawListener);
            drawListenerRegistered = true;
        }
        else if (!shouldRegister && drawListenerRegistered)
        {
            renderCallbackManager.unregister(drawListener);
            drawListenerRegistered = false;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!CONFIG_GROUP.equals(event.getGroup()))
        {
            return;
        }

        if (IGNORED_PLAYERS_CONFIG_KEY.equals(event.getKey())
            && SHARED_STORAGE_KEY.equals(event.getProfile()) && !updatingIgnoredPlayersConfig)
        {
            reloadIgnoredPlayers();
        }

        if (PLAYER_MENU_OPTION_KEY.equals(event.getKey()))
        {
            syncAddIgnoreMenuItem();
        }

        if ("hidePlayers".equals(event.getKey()))
        {
            syncDrawListener();
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (isNativeAddNameAction(event))
        {
            nativeIgnoreNamesBeforeAddAttempt.clear();
            nativeIgnoreNamesBeforeAddAttempt.addAll(getNativeIgnoreCurrentNames());
            nativeAddObserved = false;
            pendingNativeAddFallbackName = null;
            nativeAddDialogBaseline = sanitizeCandidateName(client.getVarcStrValue(VarClientID.LAST_NAMEDIALOG));
            nativeAddMesLayerBaseline = sanitizeCandidateName(client.getVarcStrValue(VarClientID.MESLAYERINPUT));
            nativeAddChatInputBaseline = sanitizeCandidateName(client.getVarcStrValue(VarClientID.CHATINPUT));
            pendingNativeIgnoreImportTicks = NATIVE_ACTION_SYNC_TICKS;
        }

        if (isNativeDelNameAction(event) && provideConfig().syncRemoveIgnore())
        {
            pendingNativeIgnoreRemovalTicks = NATIVE_ACTION_SYNC_TICKS;
        }

        if (ADD_IGNORE_MENU_OPTION.equals(event.getMenuOption()))
        {
            String playerName = getClickedPlayerName(event);
            if (playerName == null || playerName.isEmpty())
            {
                return;
            }

            addIgnoredPlayer(playerName);
            return;
        }

        if (!provideConfig().syncRemoveIgnore())
        {
            return;
        }

        if (!isNativeRemoveIgnoreAction(event))
        {
            return;
        }

        String playerName = getClickedPlayerName(event);
        if (playerName == null || playerName.isEmpty())
        {
            return;
        }

        removeIgnoredPlayerByName(playerName);
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!provideConfig().ignoreListMenuOption())
        {
            return;
        }

        int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
        if ((groupId != InterfaceID.IGNORE && groupId != InterfaceID.GIM_SIDEPANEL)
            || (!REMOVE_IGNORE_MENU_OPTION.equals(event.getOption()) && !REMOVE_GIM_IGNORE_MENU_OPTION.equals(event.getOption())))
        {
            return;
        }

        client.getMenu().createMenuEntry(-1)
            .setOption(ADD_TO_EXTENDED_MENU_OPTION)
            .setTarget(event.getTarget())
            .setType(MenuAction.RUNELITE)
            .onClick(entry -> addIgnoredPlayer(extractPlayerName(entry.getTarget())));
    }

    @Subscribe
    public void onSessionOpen(SessionOpen sessionOpen)
    {
        reloadIgnoredPlayers();
    }

    @Subscribe
    public void onSessionClose(SessionClose sessionClose)
    {
        reloadIgnoredPlayers();
    }

    @Subscribe
    public void onProfileChanged(ProfileChanged event)
    {
        reloadIgnoredPlayers();
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        clientThread.invoke(() ->
        {
            if (activeConfig != null)
            {
                pendingNativeIgnoreImportTicks = 0;
                pendingNativeIgnoreRemovalTicks = 0;
                loadIgnoredPlayersForCurrentSession();
                refreshPanelPlayers();
            }
        });
    }

    private void reloadIgnoredPlayers()
    {
        clientThread.invoke(() ->
        {
            if (activeConfig != null)
            {
                loadIgnoredPlayersForCurrentSession();
                refreshPanelPlayers();
            }
        });
    }

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        boolean nativeChanged = syncIgnoredPlayersWithNativeContainer();
        boolean pendingActionActive = pendingNativeIgnoreImportTicks > 0 || pendingNativeIgnoreRemovalTicks > 0;
        boolean pendingChanged = syncPendingNativeIgnoreActions();
        if (nativeChanged || pendingActionActive)
        {
            updateNativeIgnoreSnapshot();
        }
        if (nativeChanged || pendingChanged)
        {
            refreshPanelPlayers();
        }
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!CHAT_FILTER_CHECK_EVENT.equals(event.getEventName()))
        {
            return;
        }

        int[] intStack = client.getIntStack();
        int intStackSize = client.getIntStackSize();
        if (intStackSize < 3)
        {
            return;
        }

        ChatMessageType chatMessageType = ChatMessageType.of(intStack[intStackSize - 2]);
        if (!FILTERED_CHAT_TYPES.contains(chatMessageType))
        {
            return;
        }

        MessageNode messageNode = client.getMessages().get(intStack[intStackSize - 1]);
        if (messageNode == null || !isIgnoredPlayerName(messageNode.getName()))
        {
            return;
        }

        intStack[intStackSize - 3] = 0;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!provideConfig().ignoreTrades() || event.getType() != ChatMessageType.TRADEREQ)
        {
            return;
        }

        String message = event.getMessage();
        if (message == null || !message.contains("wishes to trade with you."))
        {
            return;
        }

        String senderName = event.getName() == null ? null : Text.removeTags(event.getName());
        if (senderName == null || senderName.isEmpty() || !isIgnoredPlayerName(senderName))
        {
            return;
        }

        MessageNode messageNode = event.getMessageNode();
        if (messageNode != null)
        {
            messageNode.setRuneLiteFormatMessage("");
            messageNode.setValue("");
        }
    }

    private void handleImportIgnoreList()
    {
        if (!canImportNativeIgnores())
        {
            refreshImportButtonState();
            return;
        }

        log.debug("Import ignore list requested.");
        importMissingNativeIgnores();
        refreshPanelPlayers();
    }

    private boolean importMissingNativeIgnores()
    {
        NameableContainer<Ignore> ignoreContainer = client.getIgnoreContainer();
        if (ignoreContainer == null)
        {
            return false;
        }

        Ignore[] members = ignoreContainer.getMembers();
        if (members == null || members.length == 0)
        {
            return false;
        }

        boolean changed = false;
        for (Ignore member : members)
        {
            if (member == null)
            {
                continue;
            }

            String currentName = member.getName();
            if (currentName == null || currentName.isEmpty())
            {
                continue;
            }

            IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(currentName);
            if (ignoredPlayer == null)
            {
                ignoredPlayer = new IgnoredPlayer(currentName);
                ignoredPlayers.put(normalizeName(currentName), ignoredPlayer);
                changed = true;
            }

            String previousName = member.getPrevName();
            if (previousName != null && !previousName.isEmpty())
            {
                int aliasesBefore = ignoredPlayer.getAliases().size();
                ignoredPlayer.addAlias(previousName);
                changed |= aliasesBefore != ignoredPlayer.getAliases().size();
            }
        }

        if (changed)
        {
            nativeIgnoreFingerprint = null;
            persistIgnoredPlayers();
        }

        return changed;
    }

    private void refreshPanelPlayers()
    {
        syncIgnoredPlayersWithNativeContainer();
        updatePanelPlayers();
    }

    private void updatePanelPlayers()
    {
        rebuildIgnoredNameIndex();
        if (panel != null)
        {
            panel.setPlayers(getIgnoredPlayers());
        }

        refreshImportButtonState();
    }

    private void refreshImportButtonState()
    {
        if (panel == null)
        {
            return;
        }

        String accountStorageKey = getAccountStorageKey();
        if (accountStorageKey == null)
        {
            panel.setImportButtonState(false, "Log in to import your ignore list.");
            return;
        }

        int missingEntries = countMissingNativeIgnoreEntries();
        if (missingEntries < 0)
        {
            return;
        }

        if (missingEntries <= 0)
        {
            panel.setImportButtonState(false, "No new native ignore list entries to import.");
            return;
        }

        panel.setImportButtonState(true, null);
    }

    private boolean canImportNativeIgnores()
    {
        return getAccountStorageKey() != null && countMissingNativeIgnoreEntries() > 0;
    }

    private int countMissingNativeIgnoreEntries()
    {
        NameableContainer<Ignore> ignoreContainer = client.getIgnoreContainer();
        if (ignoreContainer == null)
        {
            return -1;
        }

        Ignore[] members = ignoreContainer.getMembers();
        if (members == null)
        {
            return -1;
        }

        if (members.length == 0)
        {
            return 0;
        }

        int missingEntries = 0;
        for (Ignore member : members)
        {
            if (member == null)
            {
                continue;
            }

            String currentName = member.getName();
            if (currentName == null || currentName.isEmpty())
            {
                continue;
            }

            IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(currentName);
            if (ignoredPlayer == null)
            {
                missingEntries++;
            }
        }

        return missingEntries;
    }

    private void loadIgnoredPlayersForCurrentSession()
    {
        ignoredPlayers.clear();
        ignoredNameIndex.clear();
        nativeIgnoreFingerprint = null;
        previousNativeIgnoreNames.clear();

        mergeSerializedIgnoredPlayers(configManager.getConfiguration(CONFIG_GROUP, SHARED_STORAGE_KEY, IGNORED_PLAYERS_CONFIG_KEY));
        migrateIgnoredPlayers();
        rebuildIgnoredNameIndex();
    }

    private void mergeSerializedIgnoredPlayers(String serializedPlayers)
    {
        if (serializedPlayers == null || serializedPlayers.isEmpty())
        {
            return;
        }

        List<IgnoredPlayer> loadedPlayers = new ArrayList<>();
        String[] rows = serializedPlayers.split("\\n");
        for (String row : rows)
        {
            if (row.isEmpty())
            {
                continue;
            }

            String[] parts = row.split("\\t", -1);
            if (parts.length == 0)
            {
                log.debug("Skipping malformed ignored player row: {}", row);
                continue;
            }

            if (SERIALIZED_ROW_VERSION.equalsIgnoreCase(parts[0])
                || LEGACY_SERIALIZED_ROW_VERSION.equalsIgnoreCase(parts[0]))
            {
                if (parts.length < 2)
                {
                    log.debug("Skipping malformed versioned ignored player row: {}", row);
                    continue;
                }

                IgnoredPlayer ignoredPlayer = new IgnoredPlayer(parts[1]);
                if (parts.length > 2 && !parts[2].isEmpty())
                {
                    String[] aliases = parts[2].split("\\|", -1);
                    for (String alias : aliases)
                    {
                        ignoredPlayer.addAlias(alias);
                    }
                }

                if (SERIALIZED_ROW_VERSION.equalsIgnoreCase(parts[0]) && parts.length > 3)
                {
                    ignoredPlayer.setNote(parts[3]);
                }

                loadedPlayers.add(ignoredPlayer);
                continue;
            }

            if (isLegacySerializedId(parts[0]))
            {
                if (parts.length < 2)
                {
                    log.debug("Skipping malformed legacy ignored player row: {}", row);
                    continue;
                }

                loadedPlayers.add(new IgnoredPlayer(parts[1]));
                continue;
            }

            IgnoredPlayer ignoredPlayer = new IgnoredPlayer(parts[0]);
            if (parts.length > 1 && !parts[1].isEmpty())
            {
                String[] aliases = parts[1].split("\\|", -1);
                for (String alias : aliases)
                {
                    ignoredPlayer.addAlias(alias);
                }
            }

            loadedPlayers.add(ignoredPlayer);
        }

        for (IgnoredPlayer player : loadedPlayers)
        {
            String normalizedName = normalizeName(player.getCurrentName());
            if (normalizedName == null)
            {
                log.debug("Skipping ignored player with an empty name");
                continue;
            }

            IgnoredPlayer existing = findIgnoredPlayerByName(player.getCurrentName());
            if (existing == null)
            {
                for (String alias : player.getAliases())
                {
                    existing = findIgnoredPlayerByName(alias);
                    if (existing != null)
                    {
                        break;
                    }
                }
            }

            if (existing == null)
            {
                ignoredPlayers.put(normalizedName, player);
            }
            else
            {
                existing.addAlias(player.getCurrentName());
                existing.addAliases(player.getAliases());
                if (!player.getNote().isEmpty() && !existing.getNote().equals(player.getNote()))
                {
                    existing.setNote(existing.getNote().isEmpty()
                        ? player.getNote() : existing.getNote() + " / " + player.getNote());
                }
            }
        }
    }

    private void migrateIgnoredPlayers()
    {
        String profilePlayers = configManager.getConfiguration(CONFIG_GROUP, IGNORED_PLAYERS_CONFIG_KEY);
        boolean migrateProfile = profilePlayers != null && !profilePlayers.isEmpty();
        if (migrateProfile)
        {
            mergeSerializedIgnoredPlayers(profilePlayers);
        }

        Set<String> accountKeys = new LinkedHashSet<>();
        for (RuneScapeProfile profile : configManager.getRSProfiles())
        {
            accountKeys.add(profile.getKey());
        }
        String currentAccountKey = getAccountStorageKey();
        if (currentAccountKey != null)
        {
            accountKeys.add(currentAccountKey);
        }

        List<String> migratedKeys = new ArrayList<>();
        for (String accountKey : accountKeys)
        {
            if (SHARED_STORAGE_KEY.equals(accountKey))
            {
                continue;
            }

            String serializedPlayers = configManager.getConfiguration(CONFIG_GROUP, accountKey, IGNORED_PLAYERS_CONFIG_KEY);
            if (serializedPlayers != null && !serializedPlayers.isEmpty())
            {
                mergeSerializedIgnoredPlayers(serializedPlayers);
                migratedKeys.add(accountKey);
            }
        }

        if (migrateProfile || !migratedKeys.isEmpty())
        {
            persistIgnoredPlayers();
            if (migrateProfile)
            {
                configManager.unsetConfiguration(CONFIG_GROUP, IGNORED_PLAYERS_CONFIG_KEY);
            }
            for (String accountKey : migratedKeys)
            {
                configManager.unsetConfiguration(CONFIG_GROUP, accountKey, IGNORED_PLAYERS_CONFIG_KEY);
            }
        }
    }

    private void persistIgnoredPlayers()
    {
        StringBuilder serializedPlayers = new StringBuilder();
        for (IgnoredPlayer player : ignoredPlayers.values())
        {
            if (serializedPlayers.length() > 0)
            {
                serializedPlayers.append('\n');
            }

            serializedPlayers.append(SERIALIZED_ROW_VERSION)
                .append('\t')
                .append(player.getCurrentName())
                .append('\t');

            List<String> aliases = player.getAliases();
            if (!aliases.isEmpty())
            {
                serializedPlayers.append(String.join("|", aliases));
            }

            serializedPlayers.append('\t').append(sanitizeNote(player.getNote()));
        }

        updatingIgnoredPlayersConfig = true;
        try
        {
            if (ignoredPlayers.isEmpty())
            {
                configManager.unsetConfiguration(CONFIG_GROUP, SHARED_STORAGE_KEY, IGNORED_PLAYERS_CONFIG_KEY);
            }
            else
            {
                configManager.setConfiguration(CONFIG_GROUP, SHARED_STORAGE_KEY, IGNORED_PLAYERS_CONFIG_KEY, serializedPlayers.toString());
            }
        }
        finally
        {
            updatingIgnoredPlayersConfig = false;
        }
    }

