    private String extractPlayerName(String menuTarget)
    {
        String withoutTags = menuTarget.replaceAll("<[^>]+>", "").trim();
        int levelSuffix = withoutTags.indexOf("  (");
        if (levelSuffix >= 0)
        {
            return withoutTags.substring(0, levelSuffix).trim();
        }

        return withoutTags;
    }

